e_code\":\"sk\",\"enabled\":true,\"url_path\":\"/sk/library/bg/5/2/\"},{\"display_name\":\"Slovenščina (Slovenian)\",\"language_code\":\"sl\",\"enabled\":true,\"url_path\":\"/sl/library/bg/5/2/\"},{\"display_name\":\"Українська мова (Ukrainian)\",\"language_code\":\"uk\",\"enabled\":true,\"url_path\":\"/uk/library/bg/5/2/\"},{\"display_name\":\"isiZulu (Zulu)\",\"language_code\":\"zu\",\"enabled\":false,\"url_path\":\"/zu/\"}],\"breadcrumb\":[{\"url_path\":\"/en/library/\",\"title\":\"Library\"},{\"url_path\":\"/en/library/bg/\",\"title\":\"Bhagavad-gītā As It Is\"},{\"url_path\":\"/en/library/bg/5/\",\"title\":\"Chapter Five: Karma-yoga – Action in Kṛṣṇa Consciousness\"}],\"url_path\":\"/en/library/bg/5/2/\",\"bb\":1382,\"has_advanced_view\":false,\"pager\":{\"previous\":{\"url_path\":\"/en/library/bg/5/1/\",\"title\":\"TEXT 1\",\"has_advanced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]},\"next\":{\"url_path\":\"/en/library/bg/5/3/\",\"title\":\"TEXT 3\",\"has_advanced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]}},\"child_items\":[{\"section\":\"devanagari\",\"section_title\":\"Books.Verse.devanagari\",\"children\":[{\"type\":\"content.DevanagariRecord\",\"title\":\"devanagari\",\"id\":1561,\"bb\":568082,\"url_path\":\"/en/library/bg/5/2/devanagari/\",\"body_final\":\"श्रीभगवानुवाच
सन्न्यास: कर्मयोगश्च नि:श्रेयसकरावुभौ ।
तयोस्तु कर्मसन्न्यासात्कर्मयोगो विशिष्यते ॥ २ ॥\"}]},{\"section\":\"verse_text\",\"section_title\":\"Books.Verse.verse-text\",\"children\":[{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":1562,\"bb\":1384,\"url_path\":\"/en/library/bg/5/2/b1384/\",\"body_value\":\"śrī-bhagavān uvāca
sannyāsaḥ karma-yogaś ca
niḥśreyasa-karāv ubhau
tayos tu karma-sannyāsāt
karma-yogo viśiṣyate\"}]},{\"section\":\"synonyms\",\"section_title\":\"Books.Verse.synonyms\",\"children\":[{\"type\":\"books.Synonyms\",\"title\":\"synonyms\",\"id\":1563,\"bb\":1385,\"url_path\":\"/en/library/bg/5/2/b1385/\",\"shadow_value\":\"śrī-bhagavān uvāca – the Personality of Godhead said; sannyāsaḥ – renunciation of work; karma-yogaḥ – work in devotion; ca – also; niḥśreyasa-karau – leading to the path of liberation; ubhau – both; tayoḥ – of the two; tu – but; karma-sannyāsāt – in comparison to the renunciation of fruitive work; karma-yogaḥ – work in devotion; viśiṣyate – is better.\",\"word_for_word_value\":[{\"word\":\"śrī-bhagavān uvāca\",\"translation\":\"the Personality of Godhead said\"},{\"word\":\"sannyāsaḥ\",\"translation\":\"renunciation of work\"},{\"word\":\"karma-yogaḥ\",\"translation\":\"work in devotion\"},{\"word\":\"ca\",\"translation\":\"also\"},{\"word\":\"niḥśreyasa-karau\",\"translation\":\"leading to the path of liberation\"},{\"word\":\"ubhau\",\"translation\":\"both\"},{\"word\":\"tayoḥ\",\"translation\":\"of the two\"},{\"word\":\"tu\",\"translation\":\"but\"},{\"word\":\"karma-sannyāsāt\",\"translation\":\"in comparison to the renunciation of fruitive work\"},{\"word\":\"karma-yogaḥ\",\"translation\":\"work in devotion\"},{\"word\":\"viśiṣyate\",\"translation\":\"is better\"}]}]},{\"section\":\"translation\",\"section_title\":\"Books.Verse.translation\",\"children\":[{\"type\":\"content.Record\",\"title\":\"translation\",\"id\":1564,\"bb\":1386,\"url_path\":\"/en/library/bg/5/2/b1386/\",\"body_value\":\"The Personality of Godhead replied: The renunciation of work and work in devotion are both good for liberation. But, of the two, work in devotional service is better than renunciation of work.\"}]},{\"section\":\"purport\",\"section_title\":\"Books.Verse.purport\",\"children\":[{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":1565,\"bb\":1387,\"url_path\":\"/en/library/bg/5/2/b1387/\",\"body_value\":\"Fruitive activities (seeking sense gratification) are cause for material bondage. As long as one is engaged in activities aimed at improving the standard of bodily comfort, one is sure to transmigrate to different types of bodies, thereby continuing material bondage perpetually. Śrīmad-Bhāgavatam (5.5.4–6) confirms this as follows:\"},{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":1566,\"bb\":1388,\"url_path\":\"/en/library/bg/5/2/b1388/\",\"body_value\":\"nūnaṁ pramattaḥ kurute vikarma
yad indriya-prītaya āpṛṇoti
na sādhu manye yata ātmano ’yam
asann api kleśa-da āsa dehaḥ\"},{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":1567,\"bb\":1389,\"url_path\":\"/en/library/bg/5/2/b1389/\",\"body_value\":\"parābhavas tāvad abodha-jāto
yāvan na jijñāsata ātma-tattvam
yāvat kriyās tāvad idaṁ mano vai
karmātmakaṁ yena śarīra-bandhaḥ\"},{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":1568,\"bb\":1390,\"url_path\":\"/en/library/bg/5/2/b1390/\",\"body_value\":\"evaṁ manaḥ karma-vaśaṁ prayuṅkte
avidyayātmany upadhīyamāne
prītir na yāvan mayi vāsudeve
na mucyate deha-yogena tāvat\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":1569,\"bb\":1391,\"url_path\":\"/en/library/bg/5/2/b1391/\",\"body_value\":\"“People are mad after sense gratification, and they do not know that this present body, which is full of miseries, is a result of one’s fruitive activities in the past. Although this body is temporary, it is always giving one trouble in many ways. Therefore, to act for sense gratification is not good. One is considered to be a failure in life as long as he makes no inquiry about his real identity. As long as he does not know his real identity, he has to work for fruitive results for sense gratification, and as long as one is engrossed in the consciousness of sense gratification one has to transmigrate from one body to another. Although the mind may be engrossed in fruitive activities and influenced by ignorance, one must develop a love for devotional service to Vāsudeva. Only then can one have the opportunity to get out of the bondage of material existence.”\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":1570,\"bb\":1392,\"url_path\":\"/en/library/bg/5/2/b1392/\",\"body_value\":\"Therefore, jñāna (or knowledge that one is not this material body but spirit soul) is not sufficient for liberation. One has to act in the status of spirit soul, otherwise there is no escape from material bondage. Action in Kṛṣṇa consciousness is not, however, action on the fruitive platform. Activities performed in full knowledge strengthen one’s advancement in real knowledge. Without Kṛṣṇa consciousness, mere renunciation of fruitive activities does not actually purify the heart of a conditioned soul. As long as the heart is not purified, one has to work on the fruitive platform. But action in Kṛṣṇa consciousness automatically helps one escape the result of fruitive action so that one need not descend to the material platform. Therefore action in Kṛṣṇa consciousness is always superior to renunciation, which always entails a risk of falling. Renunciation without Kṛṣṇa consciousness is incomplete, as is confirmed by Śrīla Rūpa Gosvāmī in his Bhakti-rasāmṛta-sindhu (1.2.258):\"},{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":1571,\"bb\":1393,\"url_path\":\"/en/library/bg/5/2/b1393/\",\"body_value\":\"prāpañcikatayā buddhyā
hari-sambandhi-vastunaḥ
mumukṣubhiḥ parityāgo
vairāgyaṁ phalgu kathyate\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":1572,\"bb\":1394,\"url_path\":\"/en/library/bg/5/2/b1394/\",\"body_value\":\"“When persons eager to achieve liberation renounce things related to the Supreme Personality of Godhead, thinking them to be material, their renunciation is called incomplete.” Renunciation is complete when it is in the knowledge that everything in existence belongs to the Lord and that no one should claim proprietorship over anything. One should understand that, factually, nothing belongs to anyone. Then where is the question of renunciation? One who knows that everything is Kṛṣṇa’s property is always situated in renunciation. Since everything belongs to Kṛṣṇa, everything should be employed in the service of Kṛṣṇa. This perfect form of action in Kṛṣṇa consciousness is far better than any amount of artificial renunciation by a sannyāsī of the Māyāvādī school.\"}]}],\"short_title\":\"Bg. 5.2\",\"medium_title\":\"Bhagavad-gītā As It Is 5.2\"},\"locale\":\"en\",\"activeView\":\"$6:props:activeView\"}]}],\"$L25\",\"$L26\",\"$L27\"]}]\n"])self.__next_f.push([1,"29:I[83068,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n2f:I[78455,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n25:[\"$\",\"div\",null,{\"className\":\"px-4 py-4 w-f